def _parse_svg_path(d: str):
    """将 SVG path data 字符串解析为 matplotlib Path 对象。"""
    import re

    from matplotlib.path import Path

    # 匹配命令字母和数字序列
    tokens = re.findall(r'[a-zA-Z]|-?\d*\.?\d+(?:[eE][+-]?\d+)?', d)
    if not tokens:
        return Path([(0, 0)])

    vertices: list[tuple[float, float]] = []
    codes: list[int] = []

    i = 0
    cur_x, cur_y = 0.0, 0.0
    start_x, start_y = 0.0, 0.0

    while i < len(tokens):
        cmd = tokens[i]
        i += 1

        if cmd in ("M", "L", "C", "Q", "A", "S", "T", "Z", "m", "l", "c", "q", "a", "s", "t", "z"):
            if cmd in ("Z", "z"):
                vertices.append((start_x, start_y))
                codes.append(Path.CLOSEPOLY)
                cur_x, cur_y = start_x, start_y
                continue

            is_relative = cmd.islower()
            cmd_upper = cmd.upper()

            while i < len(tokens) and not tokens[i].isalpha():
                if cmd_upper == "M" or cmd_upper == "L":
                    x, y = float(tokens[i]), float(tokens[i + 1])
                    i += 2
                    if is_relative:
                        x += cur_x
                        y += cur_y
                    vertices.append((x, y))
                    codes.append(Path.MOVETO if cmd_upper == "M" and not vertices[:-1] else Path.LINETO)
                    if cmd_upper == "M":
                        start_x, start_y = x, y
                        # 后续 M 命令的隐式 L
                        cmd_upper = "L"
                    cur_x, cur_y = x, y
                elif cmd_upper == "C":
                    # 三次贝塞尔
                    x1, y1 = float(tokens[i]), float(tokens[i + 1])
                    x2, y2 = float(tokens[i + 2]), float(tokens[i + 3])
                    x, y = float(tokens[i + 4]), float(tokens[i + 5])
                    i += 6
                    if is_relative:
                        x1 += cur_x; y1 += cur_y
                        x2 += cur_x; y2 += cur_y
                        x += cur_x; y += cur_y
                    vertices.append((x1, y1))
                    codes.append(Path.CURVE4)
                    vertices.append((x2, y2))
                    codes.append(Path.CURVE4)
                    vertices.append((x, y))
                    codes.append(Path.CURVE4)
                    cur_x, cur_y = x, y
                elif cmd_upper == "Q":
                    # 二次贝塞尔
                    x1, y1 = float(tokens[i]), float(tokens[i + 1])
                    x, y = float(tokens[i + 2]), float(tokens[i + 3])
                    i += 4
                    if is_relative:
                        x1 += cur_x; y1 += cur_y
                        x += cur_x; y += cur_y
                    vertices.append((x1, y1))
                    codes.append(Path.CURVE3)
                    vertices.append((x, y))
                    codes.append(Path.CURVE3)
                    cur_x, cur_y = x, y
                elif cmd_upper == "A":
                    # 圆弧（简化为直线）
                    rx, ry = float(tokens[i]), float(tokens[i + 1])
                    i += 7  # 跳过 rx, ry, x-rot, large-arc, sweep, x, y
                    x, y = float(tokens[i - 2]), float(tokens[i - 1])
                    if is_relative:
                        x += cur_x
                        y += cur_y
                    vertices.append((x, y))
                    codes.append(Path.LINETO)
                    cur_x, cur_y = x, y
                else:
                    break
        else:
            i += 1

    if not vertices:
        vertices = [(0, 0)]
        codes = [Path.MOVETO]

    return Path(vertices, codes)


def render_icon_png(
    name: str,
    width_px: float,
    height_px: float,
    color: Optional[str] = None,
) -> bytes:
    """渲染 FontAwesome 图标为 PNG bytes。

    Args:
        name: 图标名（见 ICONS 字典）
        width_px: 目标宽度
        height_px: 目标高度
        color: 图标颜色 hex（如 "#1E293B"）

    Returns:
        PNG 图片字节流
    """
    if name not in ICONS:
        raise render_error(
            ErrorCode.RENDER_OOXML_FAILED,
            reason=f"未知图标 '{name}'，内置图标: {', '.join(sorted(ICONS)[:10])}...（共 {len(ICONS)} 个）",
        )

    try:
        import matplotlib
        matplotlib.use("Agg")
        import matplotlib.pyplot as plt
        from matplotlib.path import Path
    except ImportError:
        raise render_error(
            ErrorCode.RENDER_OOXML_FAILED,
            reason="matplotlib 未安装，图标渲染不可用。请安装：pip install matplotlib",
        )

    vb_w, vb_h, path_d = ICONS[name]
    path = _parse_svg_path(path_d)

    dpi = 150
    fig_w = max(width_px / dpi, 0.5)
    fig_h = max(height_px / dpi, 0.5)

    icon_color = color or "#1E293B"

    try:
        fig, ax = plt.subplots(figsize=(fig_w, fig_h), dpi=dpi)
        fig.patch.set_alpha(0)
        ax.set_facecolor("none")
        ax.set_xlim(0, vb_w)
        ax.set_ylim(vb_h, 0)  # SVG y 轴向下
        ax.set_aspect("equal")
        ax.axis("off")

        from matplotlib.patches import PathPatch

        patch = PathPatch(path, facecolor=icon_color, edgecolor="none")
        ax.add_patch(patch)

        buf = io.BytesIO()
        fig.savefig(buf, format="png", transparent=True, bbox_inches="tight", pad_inches=0.02)
        plt.close(fig)
        buf.seek(0)
        return buf.getvalue()
    except Exception as exc:  # noqa: BLE001
        plt.close("all")
        raise render_error(
            ErrorCode.RENDER_OOXML_FAILED,
            reason=f"图标渲染失败 ({name}): {exc}",
        ) from exc
